import type { ReactNode } from 'react';
import { useRef } from 'react';

import { useIntl } from 'react-intl';

import {
  EPageType,
  KEYBOARD_AWARE_SCROLL_BOTTOM_OFFSET,
  Keyboard,
  ScrollView,
  SizableText,
  XStack,
  YStack,
  useMedia,
} from '@onekeyhq/components';
import type { EJotaiContextStoreNames } from '@onekeyhq/kit-bg/src/states/jotai/atoms';
import { ETranslations } from '@onekeyhq/shared/src/locale';
import { ESwapTabSwitchType } from '@onekeyhq/shared/types/swap/types';
import type {
  ESwapDirectionType,
  IFetchQuoteResult,
  ISwapAlertState,
  ISwapToken,
} from '@onekeyhq/shared/types/swap/types';

import SwapProviderListPanel from '../../components/SwapProviderListPanel';
import SwapRecentTokenPairsGroup from '../../components/SwapRecentTokenPairsGroup';
import {
  SWAP_DESKTOP_CARD_SHADOW_NATIVE_STYLE,
  SWAP_DESKTOP_CARD_SHADOW_WEB_STYLE,
} from '../../utils/swapDesktopCardShadow';

import LimitInfoContainer from './LimitInfoContainer';
import LimitOrderOpenItem from './LimitOrderOpenItem';
import SwapActionsState from './SwapActionsState';
import SwapAlertContainer from './SwapAlertContainer';
import SwapHeaderRightActionContainer from './SwapHeaderRightActionContainer';
import SwapPendingHistoryListComponent from './SwapPendingHistoryList';
import SwapQuoteInput from './SwapQuoteInput';
import SwapQuoteResult from './SwapQuoteResult';
import { SwapQuoteStockMarketStatusAlert } from './SwapQuoteStockMarketStatusAlert';
import SwapTipsContainer from './SwapTipsContainer';

import type { KeyboardAwareScrollViewRef } from 'react-native-keyboard-controller';

interface ISwapOldSwapBridgeLimitContainerProps {
  pageType?: EPageType;
  storeName: EJotaiContextStoreNames;
  onSelectToken: (type: ESwapDirectionType) => void;
  fetchLoading: boolean;
  onSelectPercentageStage: (stage: number) => void;
  onBalanceMaxPress: () => void;
  onPreSwap: () => void;
  onToAnotherAddressModal: () => void;
  onOpenProviderList: () => void;
  refreshAction: () => void;
  quoteResult?: IFetchQuoteResult;
  quoteLoading: boolean;
  quoteEventFetching: boolean;
  swapTypeSwitch: ESwapTabSwitchType;
  routeSwapType?: ESwapTabSwitchType;
  alerts: {
    states: ISwapAlertState[];
    quoteId: string;
  };
  isWrapped: boolean;
  onSelectRecentTokenPairs: ({
    fromToken,
    toToken,
  }: {
    fromToken: ISwapToken;
    toToken: ISwapToken;
  }) => void;
  fromTokenAmountValue: string;
  swapRecentTokenPairs: { fromToken: ISwapToken; toToken: ISwapToken }[];
  headerContent?: ReactNode;
  hasExternalHeader?: boolean;
  hideSwapTips?: boolean;
  hideRecentTokenPairs?: boolean;
}

const SwapOldSwapBridgeLimitContainer = ({
  pageType,
  storeName,
  onSelectToken,
  fetchLoading,
  onSelectPercentageStage,
  onBalanceMaxPress,
  onPreSwap,
  onToAnotherAddressModal,
  onOpenProviderList,
  refreshAction,
  quoteResult,
  quoteLoading,
  quoteEventFetching,
  swapTypeSwitch,
  routeSwapType,
  alerts,
  isWrapped,
  onSelectRecentTokenPairs,
  fromTokenAmountValue,
  swapRecentTokenPairs,
  headerContent,
  hasExternalHeader,
  hideSwapTips,
  hideRecentTokenPairs,
}: ISwapOldSwapBridgeLimitContainerProps) => {
  const scrollViewRef = useRef<KeyboardAwareScrollViewRef>(null);
  const bottomOffset = KEYBOARD_AWARE_SCROLL_BOTTOM_OFFSET + 60;
  const { gtLg } = useMedia();
  const intl = useIntl();

  const stockLabel = intl.formatMessage({
    id: ETranslations.perps_token_selector_stocks,
  });

  // Plain static title: the swap/bridge halves used to be emphasized by the
  // current route type, which users read as a clickable toggle. Share the
  // header tab's key so the label and its connector stay locale-correct
  // (OK-58055).
  let swapTitleContent = (
    <SizableText size="$headingLg" numberOfLines={1}>
      {intl.formatMessage({ id: ETranslations.swap_history_title })}
    </SizableText>
  );
  if (swapTypeSwitch === ESwapTabSwitchType.STOCK) {
    swapTitleContent = (
      <SizableText size="$headingLg">{stockLabel}</SizableText>
    );
  } else if (swapTypeSwitch === ESwapTabSwitchType.LIMIT) {
    swapTitleContent = (
      <SizableText size="$headingLg">
        {intl.formatMessage({ id: ETranslations.swap_page_limit })}
      </SizableText>
    );
  }

  // Desktop: show provider panel on the right side
  // Show when: on large desktop (gtLg), not in modal, and not in Limit mode
  const showDesktopProviderPanel =
    gtLg &&
    pageType !== EPageType.modal &&
    swapTypeSwitch !== ESwapTabSwitchType.LIMIT &&
    swapTypeSwitch !== ESwapTabSwitchType.STOCK;

  const showLimitDesktopCard =
    gtLg &&
    pageType !== EPageType.modal &&
    swapTypeSwitch === ESwapTabSwitchType.LIMIT;

  const mainContent = (
    <YStack
      pt="$2.5"
      px="$5"
      gap="$5"
      flex={1}
      $gtMd={{
        flex: 'unset',
      }}
      {...(pageType !== EPageType.modal && {
        $gtLg: {
          maxWidth: 480,
          alignSelf: 'center',
          width: '100%',
        },
      })}
      pb="$5"
    >
      <LimitOrderOpenItem storeName={storeName} />
      <SwapQuoteInput
        onSelectToken={onSelectToken}
        selectLoading={fetchLoading}
        onSelectPercentageStage={onSelectPercentageStage}
        onBalanceMaxPress={onBalanceMaxPress}
      />
      {swapTypeSwitch === ESwapTabSwitchType.LIMIT && !isWrapped ? (
        <LimitInfoContainer />
      ) : null}
      <SwapActionsState
        onPreSwap={onPreSwap}
        onOpenRecipientAddress={onToAnotherAddressModal}
        onSelectPercentageStage={onSelectPercentageStage}
      />
      <SwapQuoteResult
        refreshAction={refreshAction}
        onOpenProviderList={
          showDesktopProviderPanel ? undefined : onOpenProviderList
        }
        quoteResult={quoteResult}
      />
      <SwapQuoteStockMarketStatusAlert onMarketReopen={refreshAction} />
      {alerts.states.length > 0 &&
      !quoteLoading &&
      !quoteEventFetching &&
      alerts?.quoteId === (quoteResult?.quoteId ?? '') ? (
        <SwapAlertContainer alerts={alerts.states} />
      ) : null}
      {hideRecentTokenPairs ? null : (
        <SwapRecentTokenPairsGroup
          onSelectTokenPairs={onSelectRecentTokenPairs}
          tokenPairs={swapRecentTokenPairs}
          fromTokenAmount={fromTokenAmountValue}
        />
      )}
      <SwapPendingHistoryListComponent
        pageType={pageType}
        storeName={storeName}
      />
    </YStack>
  );

  if (showDesktopProviderPanel) {
    // Clone mainContent with card styling for desktop
    const mainContentWithCard = (
      <YStack
        p="$6"
        gap="$5"
        borderRadius="$6"
        borderWidth={1}
        borderColor="$borderSubdued"
        elevationAndroid="$1"
        $platform-web={SWAP_DESKTOP_CARD_SHADOW_WEB_STYLE}
        style={SWAP_DESKTOP_CARD_SHADOW_NATIVE_STYLE}
      >
        <XStack alignItems="center" justifyContent="space-between">
          {swapTitleContent}
          <SwapHeaderRightActionContainer
            storeName={storeName}
            pageType={pageType}
            iconSize="$5"
            iconColor="$iconStrong"
            routeSwapType={routeSwapType}
          />
        </XStack>
        <LimitOrderOpenItem storeName={storeName} />
        <SwapQuoteInput
          onSelectToken={onSelectToken}
          selectLoading={fetchLoading}
          onSelectPercentageStage={onSelectPercentageStage}
          onBalanceMaxPress={onBalanceMaxPress}
        />
        <SwapActionsState
          onPreSwap={onPreSwap}
          onOpenRecipientAddress={onToAnotherAddressModal}
          onSelectPercentageStage={onSelectPercentageStage}
        />
        <SwapQuoteResult
          refreshAction={refreshAction}
          onOpenProviderList={undefined}
          quoteResult={quoteResult}
        />
        <SwapQuoteStockMarketStatusAlert onMarketReopen={refreshAction} />
        {alerts.states.length > 0 &&
        !quoteLoading &&
        !quoteEventFetching &&
        alerts?.quoteId === (quoteResult?.quoteId ?? '') ? (
          <SwapAlertContainer alerts={alerts.states} />
        ) : null}
        {hideRecentTokenPairs ? null : (
          <SwapRecentTokenPairsGroup
            onSelectTokenPairs={onSelectRecentTokenPairs}
            tokenPairs={swapRecentTokenPairs}
            fromTokenAmount={fromTokenAmountValue}
          />
        )}
        <SwapPendingHistoryListComponent
          pageType={pageType}
          storeName={storeName}
        />
      </YStack>
    );
    return (
      <ScrollView flex={1} contentContainerStyle={{ flexGrow: 1 }}>
        {hideSwapTips ? null : <SwapTipsContainer pageType={pageType} />}
        {headerContent && !hasExternalHeader ? (
          <YStack pt="$8" pb="$4">
            {headerContent}
          </YStack>
        ) : null}
        <XStack
          gap="$1"
          px="$5"
          flex={1}
          width="100%"
          maxWidth={1140}
          marginHorizontal="auto"
        >
          <YStack p="$5" flexBasis="50%">
            {mainContentWithCard}
          </YStack>
          <YStack p="$5" flexBasis="50%">
            <SwapProviderListPanel refreshAction={refreshAction} />
          </YStack>
        </XStack>
      </ScrollView>
    );
  }

  if (showLimitDesktopCard) {
    return (
      <ScrollView flex={1} contentContainerStyle={{ flexGrow: 1 }}>
        {hideSwapTips ? null : <SwapTipsContainer pageType={pageType} />}
        {headerContent && !hasExternalHeader ? (
          <YStack pt="$8" pb="$4">
            {headerContent}
          </YStack>
        ) : null}
        <YStack
          px="$5"
          pt="$6"
          pb="$5"
          width="100%"
          maxWidth={600}
          marginHorizontal="auto"
        >
          <YStack
            p="$6"
            gap="$5"
            borderRadius="$6"
            borderWidth={1}
            borderColor="$borderSubdued"
            elevationAndroid="$1"
            $platform-web={SWAP_DESKTOP_CARD_SHADOW_WEB_STYLE}
            style={SWAP_DESKTOP_CARD_SHADOW_NATIVE_STYLE}
          >
            <XStack alignItems="center" justifyContent="space-between">
              {swapTitleContent}
              <SwapHeaderRightActionContainer
                storeName={storeName}
                pageType={pageType}
                iconSize="$5"
                iconColor="$iconStrong"
                routeSwapType={routeSwapType}
              />
            </XStack>
            <LimitOrderOpenItem storeName={storeName} />
            <SwapQuoteInput
              onSelectToken={onSelectToken}
              selectLoading={fetchLoading}
              onSelectPercentageStage={onSelectPercentageStage}
              onBalanceMaxPress={onBalanceMaxPress}
            />
            {!isWrapped ? <LimitInfoContainer /> : null}
            <SwapActionsState
              onPreSwap={onPreSwap}
              onOpenRecipientAddress={onToAnotherAddressModal}
              onSelectPercentageStage={onSelectPercentageStage}
            />
            <SwapQuoteResult
              refreshAction={refreshAction}
              onOpenProviderList={undefined}
              quoteResult={quoteResult}
            />
            <SwapQuoteStockMarketStatusAlert onMarketReopen={refreshAction} />
            {alerts.states.length > 0 &&
            !quoteLoading &&
            !quoteEventFetching &&
            alerts?.quoteId === (quoteResult?.quoteId ?? '') ? (
              <SwapAlertContainer alerts={alerts.states} />
            ) : null}
            {hideRecentTokenPairs ? null : (
              <SwapRecentTokenPairsGroup
                onSelectTokenPairs={onSelectRecentTokenPairs}
                tokenPairs={swapRecentTokenPairs}
                fromTokenAmount={fromTokenAmountValue}
              />
            )}
            <SwapPendingHistoryListComponent
              pageType={pageType}
              storeName={storeName}
            />
          </YStack>
        </YStack>
      </ScrollView>
    );
  }

  return (
    <Keyboard.AwareScrollView
      keyboardShouldPersistTaps="handled"
      keyboardDismissMode="on-drag"
      ref={scrollViewRef}
      bottomOffset={bottomOffset}
    >
      {hideSwapTips ? null : <SwapTipsContainer pageType={pageType} />}
      {headerContent && !hasExternalHeader ? (
        <YStack pt="$8" pb="$4">
          {headerContent}
        </YStack>
      ) : null}
      {mainContent}
    </Keyboard.AwareScrollView>
  );
};

export default SwapOldSwapBridgeLimitContainer;
